const GST = 0.05;
const today = () => new Date().toLocaleDateString("en-CA", { year:"numeric", month:"long", day:"numeric" });
let receiptCounter = 1000;

const fmtCAD = (n) => new Intl.NumberFormat("en-CA", { style:"currency", currency:"CAD" }).format(n);
const fmtFX  = (n, code) => {
  try { return new Intl.NumberFormat("en-CA", { style:"currency", currency:code, maximumFractionDigits: code==="JPY"||code==="KRW"?0:2 }).format(n); }
  catch { return `${code} ${n.toFixed(2)}`; }
};

